use std :: fmt ; use super :: * ; # [doc = " Type discriminator for commands, agents, and custom entries."] # [doc = ""] # [doc = " Use this enum instead of string constants for type-safe discrimination"] # [doc = " between command types in listings and displays."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust,ignore"] # [doc = " let cmd_type = CommandType::Agent;"] # [doc = " info.add_key_value(\"type\", cmd_type.as_str());"] # [doc = " ```"] # [derive (Debug , Clone , Copy , PartialEq , Eq)] pub enum CommandType { # [doc = " Built-in command"] Command , # [doc = " Agent (AI assistant with specific role)"] Agent , # [doc = " User-defined custom command"] Custom , }